90	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
91	mod x509 {
92	    use std::fmt::Write;
93	
94	    pub(super) struct Cert {
95	        pub(super) subject: String,
96	        pub(super) issuer: String,
97	        pub(super) serial_hex: String,
98	        pub(super) not_before: String,
99	        pub(super) not_after: String,
100	    }
101	
102	    #[derive(Clone, Copy)]
103	    struct Tlv<'a> {
104	        tag: u8,
105	        content: &'a [u8],
106	    }
107	
108	    const TAG_INTEGER: u8 = 0x02;
109	    const TAG_BIT_STRING: u8 = 0x03;
110	    const TAG_OCTET_STRING: u8 = 0x04;
111	    const TAG_BOOLEAN: u8 = 0x01;
112	    const TAG_OID: u8 = 0x06;
113	    const TAG_SEQUENCE: u8 = 0x30;
114	    const TAG_SET: u8 = 0x31;
115	    const TAG_UTC_TIME: u8 = 0x17;
116	    const TAG_GENERALIZED_TIME: u8 = 0x18;
117	    const TAG_PRINTABLE_STRING: u8 = 0x13;
118	
119	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
120	    /// length encodings and truncated data.
121	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
122	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
123	        if tag & 0x1F == 0x1F {
124	            return Err("multi-byte tags are not supported".to_string());
125	        }
126	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
127	        let (len, header_len) = match first_len {
128	            0x00..=0x7F => (first_len as usize, 2),
129	            0x80 => return Err("indefinite length is not valid DER".to_string()),
130	            0xFF => return Err("reserved length byte".to_string()),
131	            long => {
132	                let n = (long & 0x7F) as usize;
133	                if !(1..=4).contains(&n) {
134	                    return Err("length is too large".to_string());
135	                }
136	                let bytes = buf
137	                    .get(2..2 + n)
138	                    .ok_or_else(|| "truncated long length".to_string())?;
139	                if bytes[0] == 0 {
140	                    return Err("non-minimal length encoding".to_string());
141	                }
142	                let mut len = 0usize;
143	                for &b in bytes {
144	                    len = len
145	                        .checked_shl(8)
146	                        .and_then(|l| l.checked_add(b as usize))
147	                        .ok_or_else(|| "length overflow".to_string())?;
148	                }
149	                if len < 0x80 {
150	                    return Err("non-minimal length encoding".to_string());
151	                }
152	                (len, 2 + n)
153	            }
154	        };
155	        let total = header_len
156	            .checked_add(len)
157	            .filter(|&t| t <= buf.len())
158	            .ok_or_else(|| "truncated TLV content".to_string())?;
159	        Ok((
160	            Tlv {
161	                tag,
162	                content: &buf[header_len..total],
163	            },
164	            &buf[total..],
165	        ))
166	    }
167	
168	    fn read_tagged<'a>(
169	        buf: &'a [u8],
170	        tag: u8,
171	        what: &str,
172	    ) -> Result<(Tlv<'a>, &'a [u8]), String> {
173	        let (tlv, rest) = read_tlv(buf).map_err(|e| format!("{what}: {e}"))?;
174	        if tlv.tag != tag {
175	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
176	        }
177	        Ok((tlv, rest))
178	    }
179	
180	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
181	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
182	        // signatureValue BIT STRING } — and nothing trailing.
183	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
184	        if !rest.is_empty() {
185	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
186	        }
187	
188	        let c = cert.content;
189	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
190	        let (outer_alg, c) = read_tagged(c, TAG_SEQUENCE, "outer signatureAlgorithm")?;
191	        let outer_alg = parse_signature_algorithm(outer_alg, "outer signatureAlgorithm")?;
192	        let (sig_value, c) = read_tlv(c)?;
193	        if sig_value.tag != TAG_BIT_STRING {
194	            return Err("signature must be a BIT STRING".to_string());
195	        }
196	        if sig_value.content.is_empty() || sig_value.content[0] > 7 {
197	            return Err("invalid signature BIT STRING".to_string());
198	        }
199	        if !c.is_empty() {
200	            return Err("trailing data in Certificate".to_string());
201	        }
202	
203	        // TBSCertificate ::= SEQUENCE {
204	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
205	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
206	        let t = tbs.content;
207	        let (first, t2) = read_tlv(t)?;
208	        let (version, t) = if first.tag == 0xA0 {
209	            let (ver, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
210	            if !vrest.is_empty() || ver.content.len() != 1 || ver.content[0] > 2 {
211	                return Err("invalid certificate version".to_string());
212	            }
213	            (ver.content[0], t2)
214	        } else {
215	            // No explicit version: v1 certificate.
216	            (0u8, t)
217	        };
218	
219	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
220	        let t = t3;
221	        let (tbs_alg, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
222	        let tbs_alg = parse_signature_algorithm(tbs_alg, "tbs signatureAlgorithm")?;
223	        if tbs_alg != outer_alg {
224	            return Err(mismatch_message(&outer_alg, &tbs_alg));
225	        }
226	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
227	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
228	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
229	        let (spki, t_after_spki) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
230	        check_spki(spki)?;
231	        // Optional tail of TBSCertificate, in a fixed order:
232	        //   issuerUniqueID  [1] IMPLICIT BIT STRING  (v2/v3, at most once)
233	        //   subjectUniqueID [2] IMPLICIT BIT STRING  (v2/v3, at most once)
234	        //   extensions      [3] EXPLICIT             (v3 only, at most once,
235	        //                                             and the last field)
236	        // Nothing else may follow subjectPublicKeyInfo: fields cannot be
237	        // skipped, reordered or dropped. The extensions interior is decoded in
238	        // full by `check_extensions`; the unique IDs carry BIT STRING content
239	        // directly (implicit tagging), validated by `check_bit_string`.
240	        let mut t = t_after_spki;
241	        let mut issuer_uid_seen = false;
242	        let mut subject_uid_seen = false;
243	        let mut extensions_present = false;
244	        while !t.is_empty() {
245	            let tag_hint = t.first().copied();
246	            let (field, rest) = read_tlv(t).map_err(|e| match tag_hint {
247	                Some(0x81) => format!("issuerUniqueID: {e}"),
248	                Some(0x82) => format!("subjectUniqueID: {e}"),
249	                // A truncated field whose tag is already readable can still
250	                // be located: tag 0xA3 is the extensions field.
251	                Some(0xA3) => format!("extensions field: {e}"),
252	                _ => e,
253	            })?;
254	            match field.tag {
255	                0x81 | 0x82 => {
256	                    let what = if field.tag == 0x81 {
257	                        "issuerUniqueID"
258	                    } else {
259	                        "subjectUniqueID"
260	                    };
261	                    if version < 1 {
262	                        return Err(format!(
263	                            "{what} is only allowed in v2 or v3 certificates, this is v1"
264	                        ));
265	                    }
266	                    if extensions_present {
267	                        return Err(format!(
268	                            "{what} must appear before the extensions field, \
269	                             which is the last field of tbsCertificate"
270	                        ));
271	                    }
272	                    if field.tag == 0x81 {
273	                        if issuer_uid_seen {
274	                            return Err("duplicate issuerUniqueID field".to_string());
275	                        }
276	                        if subject_uid_seen {
277	                            return Err(
278	                                "issuerUniqueID must appear before subjectUniqueID".to_string()
279	                            );
280	                        }
281	                        issuer_uid_seen = true;
282	                    } else if subject_uid_seen {
283	                        return Err("duplicate subjectUniqueID field".to_string());
284	                    } else {
285	                        subject_uid_seen = true;
286	                    }
287	                    check_bit_string(field.content, what)?;
288	                }
289	                0xA1 | 0xA2 => {
290	                    let what = if field.tag == 0xA1 {
291	                        "issuerUniqueID"
292	                    } else {
293	                        "subjectUniqueID"
294	                    };
295	                    return Err(format!(
296	                        "{what} must be an implicitly tagged primitive BIT STRING \
297	                         (tag 0x{:02X}); constructed tag 0x{:02X} is an explicit wrapper \
298	                         and is not allowed",
299	                        field.tag - 0x20,
300	                        field.tag
301	                    ));
302	                }
303	                0xA3 => {
304	                    if extensions_present {
305	                        return Err("duplicate extensions field".to_string());
306	                    }
307	                    if version != 2 {
308	                        let name = if version == 0 {
309	                            "v1"
310	                        } else {
311	                            "v2"
312	                        };
313	                        return Err(format!(
314	                            "extensions are only allowed in v3 certificates, this is {name}"
315	                        ));
316	                    }
317	                    check_extensions(field.content)?;
318	                    extensions_present = true;
319	                }
320	                other => {
321	                    return Err(format!(
322	                        "unexpected field after subjectPublicKeyInfo (tag 0x{other:02X}): \
323	                         only issuerUniqueID [1], subjectUniqueID [2] and extensions [3] \
324	                         are allowed there, and extensions must be last"
325	                    ));
326	                }
327	            }
328	            t = rest;
329	        }
330	
331	        let serial_hex = format_serial(serial.content)?;
332	        let issuer = format_name(issuer, "issuer")?;
333	        let subject = format_name(subject, "subject")?;
334	
335	        let v = validity.content;
336	        let (nb, v2) = read_tlv(v)?;
337	        let (na, v3) = read_tlv(v2)?;
338	        if !v3.is_empty() {
339	            return Err("trailing data in validity".to_string());
340	        }
341	        let not_before = format_time(nb)?;
342	        let not_after = format_time(na)?;
343	
344	        Ok(Cert {
345	            subject,
346	            issuer,
347	            serial_hex,
348	            not_before,
349	            not_after,
350	        })
351	    }
352	
353	    /// Validate the content of the extensions field, i.e. the bytes wrapped
354	    /// by `[3] EXPLICIT`:
355	    ///
356	    /// ```text
357	    /// Extensions ::= SEQUENCE SIZE (1..MAX) OF Extension
358	    /// Extension  ::= SEQUENCE {
359	    ///   extnID    OBJECT IDENTIFIER,
360	    ///   critical  BOOLEAN DEFAULT FALSE,
361	    ///   extnValue OCTET STRING }
362	    /// ```
363	    ///
364	    /// The wrapper must contain exactly one non-empty Extensions SEQUENCE.
365	    /// Every extension must contain its OID and OCTET STRING in that order,
366	    /// with at most one (DER-encoded) BOOLEAN between them and nothing after.
367	    /// Extension contents are never interpreted: unknown but well-formed
368	    /// extension OIDs are accepted and `critical: TRUE` is not a failure.
369	    fn check_extensions(wrapper: &[u8]) -> Result<(), String> {
370	        let (list, rest) = read_tagged(wrapper, TAG_SEQUENCE, "extensions")?;
371	        if !rest.is_empty() {
372	            return Err("extensions wrapper contains data after the Extensions SEQUENCE".to_string());
373	        }
374	        if list.content.is_empty() {
375	            return Err("extensions SEQUENCE is empty".to_string());
376	        }
377	
378	        let mut buf = list.content;
379	        while !buf.is_empty() {
380	            let (ext, rest) = read_tagged(buf, TAG_SEQUENCE, "extension")?;
381	            buf = rest;
382	
383	            let (oid, after_oid) = read_tagged(ext.content, TAG_OID, "extension OID")?;
384	            parse_oid(oid.content).map_err(|e| format!("extension OID: {e}"))?;
385	
386	            // critical is optional; whatever stands between the OID and the
387	            // OCTET STRING must be exactly one BOOLEAN if it is present.
388	            let (maybe_bool, after_critical) = read_tlv(after_oid)
389	                .map_err(|e| format!("extension after OID: {e}"))?;
390	            let (octets, after_octets) = if maybe_bool.tag == TAG_BOOLEAN {
391	                match maybe_bool.content {
392	                    [0xFF] => {}
393	                    [0x00] => {
394	                        return Err(
395	                            "extension critical: explicit DER encoding of DEFAULT FALSE is not allowed"
396	                                .to_string()
397	                        )
398	                    }
399	                    _ => {
400	                        return Err(
401	                            "extension critical: invalid DER encoding of BOOLEAN".to_string()
402	                        )
403	                    }
404	                }
405	                read_tagged(after_critical, TAG_OCTET_STRING, "extension value")?
406	            } else {
407	                // Not a BOOLEAN: this element must itself be the extnValue.
408	                if maybe_bool.tag != TAG_OCTET_STRING {
409	                    return Err(format!(
410	                        "extension must contain a critical BOOLEAN then an OCTET STRING, \
411	                         got tag 0x{:02X}",
412	                        maybe_bool.tag
413	                    ));
414	                }
415	                (maybe_bool, after_critical)
416	            };
417	            // An empty OCTET STRING is legal; its bytes are not interpreted.
418	            let _ = octets.content;
419	            if !after_octets.is_empty() {
420	                return Err("trailing data in extension".to_string());
421	            }
422	        }
423	        Ok(())
424	    }
425	
426	    /// SubjectPublicKeyInfo ::= SEQUENCE {
427	    ///   algorithm        AlgorithmIdentifier,
428	    ///   subjectPublicKey BIT STRING }
429	    /// Nothing may be missing and no extra elements may follow.
430	    fn check_spki(spki: Tlv) -> Result<(), String> {
431	        let (alg, rest) = read_tagged(
432	            spki.content,
433	            TAG_SEQUENCE,
434	            "subjectPublicKeyInfo algorithm identifier",
435	        )?;
436	        check_algorithm_identifier(alg)?;
437	        let (key, rest) = read_tagged(rest, TAG_BIT_STRING, "subjectPublicKey")?;
438	        check_bit_string(key.content, "subjectPublicKey")?;
439	        if !rest.is_empty() {
440	            return Err("trailing data in subjectPublicKeyInfo".to_string());
441	        }
442	        Ok(())
443	    }
444	
445	    /// AlgorithmIdentifier ::= SEQUENCE {
446	    ///   algorithm  OBJECT IDENTIFIER,
447	    ///   parameters ANY DEFINED BY algorithm OPTIONAL }
448	    /// The parameters, if present, must be exactly one complete DER TLV;
449	    /// absent parameters and an explicit NULL are both accepted. The
450	    /// parameter content is not interpreted for any particular algorithm.
451	    fn check_algorithm_identifier(alg: Tlv) -> Result<(), String> {
452	        let (oid, rest) = read_tagged(alg.content, TAG_OID, "algorithm OID")?;
453	        parse_oid(oid.content).map_err(|e| format!("algorithm OID: {e}"))?;
454	        if rest.is_empty() {
455	            return Ok(());
456	        }
457	        let (_params, after) =
458	            read_tlv(rest).map_err(|e| format!("algorithm parameters: {e}"))?;
459	        if !after.is_empty() {
460	            return Err("multiple algorithm parameters".to_string());
461	        }
462	        Ok(())
463	    }
464	
465	    /// One of the certificate's two signature algorithm descriptions, kept as
466	    /// raw slices so two copies can be compared at the DER byte level: the OID
467	    /// content (arcs in their shortest encoding) and the complete parameter
468	    /// TLV (tag, length and content), or no parameter at all. An absent
469	    /// parameter and an explicit NULL are different representations.
470	    #[derive(Clone, Copy, PartialEq, Eq)]
471	    struct SignatureAlgorithm<'a> {
472	        oid_content: &'a [u8],
473	        params: Option<&'a [u8]>,
474	    }
475	
476	    /// Parse and fully validate one signatureAlgorithm SEQUENCE: it must start
477	    /// with one complete, shortest-encoded algorithm OID, followed by either
478	    /// nothing or exactly one complete DER parameter value. `loc` names which
479	    /// of the two copies is being checked ("outer signatureAlgorithm" or the
480	    /// copy inside tbsCertificate) and prefixes every error message.
481	    fn parse_signature_algorithm<'a>(
482	        alg: Tlv<'a>,
483	        loc: &str,
484	    ) -> Result<SignatureAlgorithm<'a>, String> {
485	        let (oid, rest) = read_tlv(alg.content).map_err(|e| format!("{loc}: {e}"))?;
486	        if oid.tag != TAG_OID {
487	            return Err(format!(
488	                "{loc}: algorithm must start with an OID (tag 0x06), got tag 0x{:02X}",
489	                oid.tag
490	            ));
491	        }
492	        // Validates the OID content itself: non-empty, complete base-128 arcs
493	        // in their shortest encoding.
494	        parse_oid(oid.content).map_err(|e| format!("{loc}: {e}"))?;
495	        let params = if rest.is_empty() {
496	            None
497	        } else {
498	            let (_param, after) = read_tlv(rest)
499	                .map_err(|e| format!("{loc}: algorithm parameters: {e}"))?;
500	            if !after.is_empty() {
501	                return Err(format!(
502	                    "{loc}: extra element after the algorithm parameters"
503	                ));
504	            }
505	            // Keep the full parameter TLV (tag, length and content), sliced
506	            // straight from the enclosing content; `read_tlv` already proved
507	            // it is a complete value.
508	            let param_len = rest.len() - after.len();
509	            Some(&rest[..param_len])
510	        };
511	        Ok(SignatureAlgorithm {
512	            oid_content: oid.content,
513	            params,
514	        })
515	    }
516	
517	    /// Describe the disagreement between the outer signatureAlgorithm and the
518	    /// copy inside tbsCertificate. Both copies parse on their own; they merely
519	    /// fail to name the same algorithm or the same parameter representation.
520	    fn mismatch_message(outer: &SignatureAlgorithm<'_>, inner: &SignatureAlgorithm<'_>) -> String {
521	        const OUTER: &str = "the outer signatureAlgorithm";
522	        const INNER: &str = "the signatureAlgorithm in tbsCertificate";
523	        if outer.oid_content != inner.oid_content {
524	            let outer_oid = parse_oid(outer.oid_content)
525	                .map(|arcs| arcs_to_string(&arcs))
526	                .unwrap_or_else(|_| "?".to_string());
527	            let inner_oid = parse_oid(inner.oid_content)
528	                .map(|arcs| arcs_to_string(&arcs))
529	                .unwrap_or_else(|_| "?".to_string());
530	            return format!(
531	                "signature algorithm mismatch: {OUTER} names OID {outer_oid}, but {INNER} \
532	                 names OID {inner_oid}"
533	            );
534	        }
535	        match (outer.params, inner.params) {
536	            (Some(outer_params), Some(inner_params)) if outer_params != inner_params => {
537	                format!(
538	                    "signature algorithm mismatch: both copies name the same algorithm OID but \
539	                     their parameters have different DER encodings ({OUTER} has {}, {INNER} has {})",
540	                    hex_of(outer_params),
541	                    hex_of(inner_params),
542	                )
543	            }
544	            (Some(_), None) => format!(
545	                "signature algorithm mismatch: {OUTER} carries parameters but {INNER} omits them \
546	                 (an absent parameter and an explicit value are different representations)"
547	            ),
548	            (None, Some(_)) => format!(
549	                "signature algorithm mismatch: {INNER} carries parameters but {OUTER} omits them \
550	                 (an absent parameter and an explicit value are different representations)"
551	            ),
552	            // PartialEq already proved the copies unequal; reaching any other
553	            // arm here would be a logic error rather than a malformed cert.
554	            _ => "signature algorithm mismatch between the two signatureAlgorithm copies"
555	                .to_string(),
556	        }
557	    }
558	
559	    fn hex_of(bytes: &[u8]) -> String {
560	        let mut s = String::with_capacity(bytes.len() * 2);
561	        for b in bytes {
562	            write!(s, "{b:02X}").unwrap();
563	        }
564	        s
565	    }
566	
567	    /// Validate the DER content of a BIT STRING: one leading byte counting
568	    /// unused bits (0..=7), and when the count is nonzero those low bits of
569	    /// the final data byte must all be zero. An empty bit string is only
570	    /// legal with a zero count.
571	    fn check_bit_string(content: &[u8], what: &str) -> Result<(), String> {
572	        let unused = *content
573	            .first()
574	            .ok_or_else(|| format!("{what} BIT STRING is missing the unused-bits byte"))?;
575	        if unused > 7 {
576	            return Err(format!("{what} BIT STRING has invalid unused-bits count {unused}"));
577	        }
578	        let data = &content[1..];
579	        if data.is_empty() {
580	            if unused != 0 {
581	                return Err(format!(
582	                    "{what} BIT STRING declares {unused} unused bits but has no data"
583	                ));
584	            }
585	            return Ok(());
586	        }
587	        if unused != 0 && data[data.len() - 1] & ((1u8 << unused) - 1) != 0 {
588	            return Err(format!(
589	                "{what} BIT STRING has set bits among the {unused} unused trailing bits"
590	            ));
591	        }
592	        Ok(())
593	    }
594	
595	    /// Render the serial number as upper-case hex, matching the integer value
596	    /// (a DER sign-padding 0x00 byte is not part of the number).
597	    fn format_serial(content: &[u8]) -> Result<String, String> {
598	        if content.is_empty() {
599	            return Err("empty serial number".to_string());
600	        }
601	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
602	            return Err("non-minimal serial number encoding".to_string());
603	        }
604	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
605	            return Err("non-minimal serial number encoding".to_string());
606	        }
607	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
608	            return Err("negative serial number".to_string());
609	        }
610	        let digits = if content.len() > 1 && content[0] == 0x00 {
611	            &content[1..]
612	        } else {
613	            content
614	        };
615	        let mut s = String::with_capacity(digits.len() * 2);
616	        for b in digits {
617	            write!(s, "{b:02X}").unwrap();
618	        }
619	        if s.is_empty() {
620	            s.push_str("00");
621	        }
622	        Ok(s)
623	    }
624	
625	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
626	    /// multi-valued RDNs joined with '+'). Values of known attribute types
627	    /// are emitted as real UTF-8 text (non-ASCII content preserved verbatim)
628	    /// when their tag has a text decoder; a known type carrying any other
629	    /// readable DER value (e.g. postalAddress as a SEQUENCE) keeps its short
630	    /// name and uses the '#' form carrying the value's full DER encoding in
631	    /// hex. Attributes without a known short name use their dotted OID with
632	    /// the same '#' form.
633	    ///
634	    /// Each RDN is a DER SET OF, so its complete AttributeTypeAndValue
635	    /// encodings must be sorted by their full encoding bytes (tag, then
636	    /// length, then content — the encoding, never the display name, dotted
637	    /// OID text or decoded value). The check is per RDN; it never reorders
638	    /// the members itself. `what` names the name being checked ("subject" or
639	    /// "issuer") so an ordering failure identifies it in the error message.
640	    fn format_name(name: Tlv, what: &str) -> Result<String, String> {
641	        let mut rdn_buf = name.content;
642	        let mut rdns: Vec<String> = Vec::new();
643	        while !rdn_buf.is_empty() {
644	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
645	            rdn_buf = rest;
646	
647	            let mut atv_buf = set.content;
648	            let mut parts = Vec::new();
649	            // Raw full encoding (tag, length and content) of each member of
650	            // this SET OF, straight from the certificate: DER SET OF ordering
651	            // compares the complete member encodings byte for byte. Equal
652	            // encodings may legitimately repeat and stay adjacent.
653	            let mut members: Vec<&[u8]> = Vec::new();
654	            while !atv_buf.is_empty() {
655	                let atv_start = atv_buf;
656	                let (atv, rest) =
657	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
658	                atv_buf = rest;
659	                members.push(&atv_start[..atv_start.len() - atv_buf.len()]);
660	
661	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
662	                let (value, after_value) = read_tlv(after_oid)?;
663	                if !after_value.is_empty() {
664	                    return Err("trailing data in attribute value".to_string());
665	                }
666	
667	                let oid_arcs = parse_oid(oid.content)?;
668	
669	                // The value's own type rules apply before any display decision:
670	                // a PrintableString must hold only the RFC 5280 PrintableString
671	                // alphabet, whether the attribute later renders as text for a
672	                // known short name or as '#'-hex for an unknown type. The hex
673	                // form must never let an illegal byte through, and an illegal
674	                // byte cannot be dropped or replaced. An empty value stays
675	                // legal. `what` names the offending name ("subject"/"issuer").
676	                if value.tag == TAG_PRINTABLE_STRING
677	                    && !is_printable_string(value.content)
678	                {
679	                    return Err(format!(
680	                        "{what} name: PrintableString attribute value contains an illegal \
681	                         character (only A-Z, a-z, 0-9, space and ' ( ) + , - . / : = ? are \
682	                         allowed)"
683	                    ));
684	                }
685	
686	                match oid_short_name(&oid_arcs) {
687	                    Some(label) => {
688	                        if is_text_value_tag(value.tag) {
689	                            // Supported string type: decode to escaped text.
690	                            // A decode failure (e.g. invalid UTF-8) means the
691	                            // certificate is corrupt; it must not be salvaged
692	                            // by falling back to the hex form.
693	                            let text = decode_attribute_value(value.tag, value.content)?;
694	                            parts.push(format!("{label}={}", escape_value(&text)));
695	                        } else {
696	                            // Known type but a legal value with no text decoder
697	                            // (SEQUENCE, OCTET STRING, ...): keep the short name
698	                            // and show the full original DER encoding as '#'-hex.
699	                            parts.push(format!("{label}=#{}", value_hex(after_oid, after_value)));
700	                        }
701	                    }
702	                    None => {
703	                        // Unknown attribute type: RFC 4514 requires the form
704	                        // OID=#hex, where the hex is the full DER encoding
705	                        // (tag, length and content) of the attribute value.
706	                        // Showing the value as hex does not bypass its type
707	                        // rules: UTF8String content must be valid UTF-8 and a
708	                        // PrintableString must keep to its alphabet, checks
709	                        // already performed above before this match.
710	                        if value.tag == 0x0C {
711	                            std::str::from_utf8(value.content)
712	                                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?;
713	                        }
714	                        let hex = value_hex(after_oid, after_value);
715	                        parts.push(format!("{}=#{hex}", arcs_to_string(&oid_arcs)));
716	                    }
717	                }
718	            }
719	            if parts.is_empty() {
720	                return Err("empty RelativeDistinguishedName".to_string());
721	            }
722	            check_rdn_der_order(&members, what)?;
723	            rdns.push(parts.join("+"));
724	        }
725	        rdns.reverse();
726	        Ok(rdns.join(","))
727	    }
728	
729	    /// Validate one RDN as a DER SET OF: every member's complete
730	    /// AttributeTypeAndValue encoding must be less than or equal to the next
731	    /// one under ordinary byte ordering of tag, length and content. The
732	    /// comparison runs on the raw encodings only — CN/O short names, dotted
733	    /// OID text and decoded values never enter into it — and equal adjacent
734	    /// members (duplicate attributes) are allowed. The members are never
735	    /// reordered to make an unsorted input pass. `what` is "subject" or
736	    /// "issuer" and identifies the offending name in the error message.
737	    fn check_rdn_der_order(members: &[&[u8]], what: &str) -> Result<(), String> {
738	        for pair in members.windows(2) {
739	            if pair[0] > pair[1] {
740	                return Err(format!(
741	                    "{what} name: attributes of a multi-valued RelativeDistinguishedName \
742	                     are not encoded in DER SET OF order (the members must be sorted by \
743	                     their complete DER encoding bytes: tag, then length, then content)"
744	                ));
745	            }
746	        }
747	        Ok(())
748	    }
749	
750	    /// Uppercase hex of one complete value TLV, sliced straight from the
751	    /// input bytes (`around` ends at `rest`). The original tag and length
752	    /// bytes survive verbatim, including a legal long-form length; nothing is
753	    /// re-encoded and content alone is never emitted.
754	    fn value_hex(around: &[u8], rest: &[u8]) -> String {
755	        let tlv_len = around.len() - rest.len();
756	        let mut hex = String::with_capacity(tlv_len * 2);
757	        for b in &around[..tlv_len] {
758	            write!(hex, "{b:02X}").unwrap();
759	        }
760	        hex
761	    }
762	
763	    /// Tags whose attribute values have a direct text decoding in
764	    /// `decode_attribute_value`. Every other tag that `read_tlv` accepts is a
765	    /// legal non-text value for display purposes and is rendered as '#'-hex.
766	    fn is_text_value_tag(tag: u8) -> bool {
767	        matches!(
768	            tag,
769	            0x0C | 0x12 | 0x13 | 0x14 | 0x16 | 0x1A | 0x1B | 0x1C | 0x1E
770	        )
771	    }
772	
773	    fn parse_oid(content: &[u8]) -> Result<Vec<u64>, String> {
774	        if content.is_empty() {
775	            return Err("empty OID".to_string());
776	        }
777	        let mut arcs = Vec::new();
778	        // The first subidentifier encodes the first two arcs as
779	        // 40*first + second and is itself a base-128 quantity, so it can
780	        // span multiple content bytes (e.g. 2.999 encodes as 0x88 0x37).
781	        let mut i = 0;
782	        let first = read_oid_arc(content, &mut i)?;
783	        match first {
784	            0..=39 => {
785	                arcs.push(0);
786	                arcs.push(first);
787	            }
788	            40..=79 => {
789	                arcs.push(1);
790	                arcs.push(first - 40);
791	            }
792	            _ => {
793	                arcs.push(2);
794	                arcs.push(first - 80);
795	            }
796	        }
797	        while i < content.len() {
798	            arcs.push(read_oid_arc(content, &mut i)?);
799	        }
800	        Ok(arcs)
801	    }
802	
803	    /// Read one base-128 subidentifier starting at `*i`. Rejects trailing
804	    /// continuation bytes and non-minimal encodings.
805	    fn read_oid_arc(content: &[u8], i: &mut usize) -> Result<u64, String> {
806	        let start = *i;
807	        let mut value = 0u64;
808	        loop {
809	            let b = *content
810	                .get(*i)
811	                .ok_or_else(|| "truncated OID arc".to_string())?;
812	            value = value
813	                .checked_mul(128)
814	                .and_then(|v| v.checked_add((b & 0x7F) as u64))
815	                .ok_or_else(|| "OID arc overflow".to_string())?;
816	            *i += 1;
817	            if b & 0x80 == 0 {
818	                break;
819	            }
820	        }
821	        if *i - start > 1 && content[start] == 0x80 {
822	            return Err("non-minimal OID arc encoding".to_string());
823	        }
824	        Ok(value)
825	    }
826	
827	    fn arcs_to_string(arcs: &[u64]) -> String {
828	        arcs.iter()
829	            .map(u64::to_string)
830	            .collect::<Vec<_>>()
831	            .join(".")
832	    }
833	
834	    fn oid_short_name(arcs: &[u64]) -> Option<&'static str> {
835	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
836	        let name = match arcs {
837	            [2, 5, 4, 3] => "CN",
838	            [2, 5, 4, 4] => "SN",
839	            [2, 5, 4, 5] => "serialNumber",
840	            [2, 5, 4, 6] => "C",
841	            [2, 5, 4, 7] => "L",
842	            [2, 5, 4, 8] => "ST",
843	            [2, 5, 4, 9] => "STREET",
844	            [2, 5, 4, 10] => "O",
845	            [2, 5, 4, 11] => "OU",
846	            [2, 5, 4, 12] => "title",
847	            [2, 5, 4, 17] => "postalAddress",
848	            [2, 5, 4, 18] => "postalCode",
849	            [2, 5, 4, 20] => "telephoneNumber",
850	            [2, 5, 4, 42] => "givenName",
851	            [2, 5, 4, 43] => "initials",
852	            [2, 5, 4, 44] => "generationQualifier",
853	            [2, 5, 4, 46] => "dnQualifier",
854	            [2, 5, 4, 65] => "pseudonym",
855	            [0, 9, 2342, 19200300, 100, 1, 1] => "UID",
856	            [0, 9, 2342, 19200300, 100, 1, 25] => "DC",
857	            [1, 2, 840, 113549, 1, 9, 1] => "emailAddress",
858	            _ => return None,
859	        };
860	        Some(name)
861	    }
862	
863	    /// Whether every byte belongs to the RFC 5280 PrintableString alphabet:
864	    /// A-Z, a-z, 0-9, space, and ' ( ) + , - . / : = ?. Every other byte
865	    /// (including @, _, tabs, newlines, NUL and 0x80..=0xFF) is illegal.
866	    /// An empty value passes, preserving the existing acceptance of empty
867	    /// contents.
868	    fn is_printable_string(content: &[u8]) -> bool {
869	        content.iter().all(|&b| matches!(
870	            b,
871	            b'A'..=b'Z'
872	                | b'a'..=b'z'
873	                | b'0'..=b'9'
874	                | b' '
875	                | b'\''
876	                | b'('
877	                | b')'
878	                | b'+'
879	                | b','
880	                | b'-'
881	                | b'.'
882	                | b'/'
883	                | b':'
884	                | b'='
885	                | b'?'
886	        ))
887	    }
888	
889	    /// Decode a DirectoryString-style attribute value into UTF-8 text.
890	    fn decode_attribute_value(tag: u8, content: &[u8]) -> Result<String, String> {
891	        let s = match tag {
892	            0x0C => std::str::from_utf8(content)
893	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
894	                .to_string(),
895	            // ASCII-family strings: every byte is also its Unicode code point.
896	            0x12 | 0x13 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
897	            // T.61 / GeneralString are conventionally treated as Latin-1 here.
898	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
899	            0x1E => {
900	                if content.len() % 2 != 0 {
901	                    return Err("odd-length BMPString".to_string());
902	                }
903	                let units: Vec<u16> = content
904	                    .chunks_exact(2)
905	                    .map(|c| u16::from_be_bytes([c[0], c[1]]))
906	                    .collect();
907	                char::decode_utf16(units.iter().copied())
908	                    .map(|r| r.map_err(|_| "unpaired surrogate in BMPString".to_string()))
909	                    .collect::<Result<String, _>>()?
910	            }
911	            0x1C => {
912	                if content.len() % 4 != 0 {
913	                    return Err("invalid UniversalString length".to_string());
914	                }
915	                let mut s = String::new();
916	                for c in content.chunks_exact(4) {
917	                    let cp = u32::from_be_bytes([c[0], c[1], c[2], c[3]]);
918	                    if (0xD800..=0xDFFF).contains(&cp) || cp > 0x10FFFF {
919	                        return Err("invalid code point in UniversalString".to_string());
920	                    }
921	                    s.push(char::from_u32(cp).unwrap());
922	                }
923	                s
924	            }
925	            _ => {
926	                return Err(format!(
927	                    "unsupported attribute value string type (tag 0x{tag:02X})"
928	                ))
929	            }
930	        };
931	        Ok(s)
932	    }
933	
934	    /// RFC 4514 value escaping; everything above the ASCII control range
935	    /// (including CJK text) passes through unchanged.
936	    fn escape_value(value: &str) -> String {
937	        let mut out = String::with_capacity(value.len());
938	        let last = value.chars().count().saturating_sub(1);
939	        for (i, c) in value.chars().enumerate() {
940	            let at_edge = i == 0 || i == last;
941	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
942	                || (at_edge && (c == ' ' || c == '#'));
943	            if needs_backslash {
944	                out.push('\\');
945	                out.push(c);
946	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
947	                let mut buf = [0u8; 4];
948	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
949	                write!(out, "\\{b:02X}").unwrap();
950	            } else {
951	                out.push(c);
952	            }
953	        }
954	        out
955	    }
956	
957	    fn format_time(tlv: Tlv) -> Result<String, String> {
958	        let (y, mo, d, h, mi, se) = match tlv.tag {
959	            TAG_UTC_TIME => {
960	                let c = tlv.content;
961	                if c.len() != 13 || c[12] != b'Z' {
962	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
963	                }
964	                let digits = &c[..12];
965	                if !digits.iter().all(|b| b.is_ascii_digit()) {
966	                    return Err("non-numeric UTCTime".to_string());
967	                }
968	                let n = |a: usize, b: usize| -> u32 {
969	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
970	                };
971	                let yy = n(0, 1);
972	                let year = if yy < 50 { 2000 + yy } else { 1900 + yy };
973	                (year as i32, n(2, 3), n(4, 5), n(6, 7), n(8, 9), n(10, 11))
974	            }
975	            TAG_GENERALIZED_TIME => {
976	                let c = tlv.content;
977	                if c.len() != 15 || c[14] != b'Z' {
978	                    return Err(
979	                        "GeneralizedTime must be YYYYMMDDHHMMSSZ in UTC".to_string()
980	                    );
981	                }
982	                let digits = &c[..14];
983	                if !digits.iter().all(|b| b.is_ascii_digit()) {
984	                    return Err("non-numeric GeneralizedTime".to_string());
985	                }
986	                let n = |a: usize, b: usize| -> u32 {
987	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
988	                };
989	                (n(0, 3) as i32, n(4, 5), n(6, 7), n(8, 9), n(10, 11), n(12, 13))
990	            }
991	            other => return Err(format!("invalid time tag 0x{other:02X}")),
992	        };
993	        validate_datetime(y, mo, d, h, mi, se)?;
994	        Ok(format!("{y:04}-{mo:02}-{d:02}T{h:02}:{mi:02}:{se:02}Z"))
995	    }
996	
997	    fn validate_datetime(
998	        year: i32,
999	        month: u32,
1000	        day: u32,
1001	        hour: u32,
1002	        minute: u32,
1003	        second: u32,
1004	    ) -> Result<(), String> {
1005	        if !(1..=12).contains(&month) {
1006	            return Err("invalid month in certificate time".to_string());
1007	        }
1008	        if hour > 23 || minute > 59 || second > 59 {
1009	            return Err("invalid time of day in certificate time".to_string());
1010	        }
1011	        let leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
1012	        let days = [31, if leap { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
1013	        if day < 1 || day > days[(month - 1) as usize] {
1014	            return Err("invalid day in certificate time".to_string());
1015	        }
1016	        Ok(())
1017	    }
1018	}
