149	#[test]
150	fn known_attribute_with_sequence_value_keeps_short_name_and_shows_der_hex() {
151	    // The exact spec example: postalAddress (2.5.4.17) is a known attribute
152	    // whose value is a SEQUENCE { UTF8String "abc" } rather than a string. It
153	    // must render as postalAddress=#30050C03616263 — tag 0x30, length 0x05
154	    // and content verbatim — instead of rejecting the whole certificate.
