692	struct TempCert {
693	    path: PathBuf,
694	}
695	
696	impl TempCert {
697	    fn new(tag: &str, data: &[u8]) -> Self {
698	        static COUNTER: AtomicU64 = AtomicU64::new(0);
699	        let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
700	        let path = std::env::temp_dir().join(format!(
701	            "chainview-name-test-{}-{tag}-{unique}.der",
702	            std::process::id()
703	        ));
704	        fs::write(&path, data).expect("writing temp certificate");
705	        TempCert { path }
706	    }
707	}
