715	// ----- Certificate / DER construction -------------------------------------
716	//
717	// Only the structural pieces needed here. Lengths are always emitted in the
718	// minimal DER form, except where a test injects raw bytes to exercise
719	// rejection of non-minimal or truncated encodings.
720	
721	fn simple_cn_name(cn: &str) -> Vec<u8> {
722	    name(&[rdn(&[atv_utf8(CN, cn)])])
723	}
724	
725	/// Assemble a complete, parseable v1 DER certificate with fixed serial,
726	/// validity and key material around the supplied Subject/Issuer names.
727	fn build_cert(subject: &[u8], issuer: &[u8]) -> Vec<u8> {
728	    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
729	    let validity = seq(&concat(&[
730	        &tlv(0x17, b"260115093000Z"), // UTCTime 2026-01-15T09:30:00Z
731	        &tlv(0x17, b"270115093000Z"), // UTCTime 2027-01-15T09:30:00Z
732	    ]));
733	    let spki = seq(&concat(&[
734	        &seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 1]), &tlv(0x05, &[])])),
735	        &tlv(0x03, &[0x00, 0x01, 0x00]), // BIT STRING, zero unused bits
736	    ]));
737	
738	    let tbs = seq(&concat(&[
739	        &serial,
740	        &signature_algorithm(),
741	        issuer,
742	        &validity,
743	        subject,
744	        &spki,
745	    ]));
746	    seq(&concat(&[&tbs, &signature_algorithm(), &tlv(0x03, &[0x00])]))
747	}
748	
749	fn signature_algorithm() -> Vec<u8> {
750	    // sha256WithRSAEncryption with explicit NULL parameters.
751	    seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 11]), &tlv(0x05, &[])]))
752	}
753	
754	fn name(rdns: &[Vec<u8>]) -> Vec<u8> {
755	    tlv(
756	        0x30,
757	        &concat(&rdns.iter().map(Vec::as_slice).collect::<Vec<_>>()),
758	    )
759	}
760	
761	fn rdn(atvs: &[Vec<u8>]) -> Vec<u8> {
762	    tlv(
763	        0x31,
764	        &concat(&atvs.iter().map(Vec::as_slice).collect::<Vec<_>>()),
765	    )
766	}
767	
768	/// AttributeTypeAndValue ::= SEQUENCE { type OID, value ANY } — `value` is the
769	/// complete DER TLV of the value.
770	fn atv(arcs: &[u64], value: &[u8]) -> Vec<u8> {
771	    seq(&concat(&[&oid(arcs), value]))
772	}
773	
774	fn atv_utf8(arcs: &[u64], text: &str) -> Vec<u8> {
775	    atv(arcs, &tlv(0x0C, text.as_bytes()))
776	}
777	
778	fn atv_printable(arcs: &[u64], bytes: &[u8]) -> Vec<u8> {
779	    atv(arcs, &tlv(0x13, bytes))
780	}
781	
782	fn oid(arcs: &[u64]) -> Vec<u8> {
783	    assert!(arcs.len() >= 2);
784	    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
785	    for &arc in &arcs[2..] {
786	        content.extend_from_slice(&oid_arc(arc));
787	    }
788	    tlv(0x06, &content)
789	}
790	
791	fn oid_arc(mut value: u64) -> Vec<u8> {
792	    let mut out = vec![(value % 128) as u8];
793	    value /= 128;
794	    while value > 0 {
795	        out.push(0x80 | (value % 128) as u8);
796	        value /= 128;
797	    }
798	    out.reverse();
799	    out
800	}
801	
802	fn seq(content: &[u8]) -> Vec<u8> {
803	    tlv(0x30, content)
804	}
805	
806	fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
807	    let mut out = vec![tag];
808	    out.extend_from_slice(&der_len(content.len()));
809	    out.extend_from_slice(content);
810	    out
811	}
812	
813	fn der_len(n: usize) -> Vec<u8> {
814	    if n < 0x80 {
815	        vec![n as u8]
816	    } else {
817	        let mut body = Vec::new();
818	        let mut v = n;
819	        while v > 0 {
820	            body.push((v & 0xFF) as u8);
821	            v >>= 8;
822	        }
823	        body.reverse();
824	        let mut out = vec![0x80 | body.len() as u8];
825	        out.extend_from_slice(&body);
826	        out
827	    }
828	}
829	
830	fn concat(parts: &[&[u8]]) -> Vec<u8> {
831	    let mut out = Vec::new();
832	    for part in parts {
833	        out.extend_from_slice(part);
834	    }
835	    out
836	}
837	
838	fn hex(bytes: &[u8]) -> String {
839	    let mut s = String::with_capacity(bytes.len() * 2);
840	    for b in bytes {
841	        use std::fmt::Write;
842	        write!(s, "{b:02X}").unwrap();
843	    }
844	    s
845	}
846

